#!/usr/bin/env sh
set -eu

OUT_DIR="fuzz"
MAP_FILE="$OUT_DIR/TargetMap.yaml"
mkdir -p "$OUT_DIR"

cat >"$MAP_FILE" <<'YAML'
# Auto-generated by scripts/annotate_refs.sh
anchors:
YAML

add_anchor() {
  path="$1"
  symbol="$2"
  line=$(git grep -n "$symbol" -- "$path" | head -n 1 | cut -d: -f2)
  if [ -n "${line:-}" ]; then
    echo "  - ${path}:${line}:${symbol}" >>"$MAP_FILE"
  else
    # fallback: emit path with line 0 if not found
    echo "  - ${path}:0:${symbol}" >>"$MAP_FILE"
  fi
}

add_anchor "src/lib.zig" "pub fn parse("
add_anchor "src/gql/parser.zig" "const ParserError ="
add_anchor "src/index/hnsw_persist.zig" "fn loadSnapshot("
add_anchor "src/index/hnsw_persist.zig" "fn replayWal("
add_anchor "src/txn/manager.zig" "fn begin"
add_anchor "src/txn/manager.zig" "fn commit"
add_anchor "src/txn/manager.zig" "fn rollback"
add_anchor "src/txn/manager.zig" "TxnState.Committed"
add_anchor "src/graph/builders.zig" "Graph.init"
add_anchor "src/graph/containers/lfu.zig" "LfuU32U32"
add_anchor "tests/test_canary_core.zig" "TestCANARY_REQ_GQL_030_TxnCommit"
add_anchor "tests/test_canary_core.zig" "TestCANARY_REQ_GQL_005_HelloRoundTrip"
add_anchor "tests/test_extended_canary.zig" "DecimalFormatterRoundTrip"
add_anchor "tests/canary_planner_prune.zig" "prune"
add_anchor "tests/canary_migration_engine_new_tests.zig" "migration"
add_anchor "tools/canaryscan/scan.go" "status.json"
add_anchor "README.md" "CANARY"

echo "Wrote anchors to $MAP_FILE"
